# Code generated by Claude
"""
Headless test of the placeholder pedestal lift actuator on the imported pedestal (src/pedestal.py, robot_specs.PEDESTAL_SPECS): ONE slide joint, 0 (collapsed) to 0.418 m (raised).

    source .venv/bin/activate
    python experiments/pedestal_lift_test.py

No viewer; one MuJoCo model at a time. The robot is spawned on the floor of the lab scene with the arms held at their start pose (position servos, targets = the settled pose) and the base
stationary (velocity zeroed every step, as the velocity drive does), then the pedestal command is stepped: fully raised, mid, fully collapsed, raised again.

Checks
  1. The load the lift carries (mass above the joint) and the static sag it gives at the servo's kp.
  2. For each setpoint: the joint gets within 2 mm of the command, holds it within 1.5 mm for 3 s, the torso stands 0.3048 + command above the pedestal base (within 2 mm), and the actuator's
     force at the end of the hold equals the weight it carries (within 15 %; at the collapsed limit: at most that weight, the joint limit may take part of it). Gravity compensation carries
     the arms, so the load is the pedestal's moving part, the torso, the camera box, the battery-free upper body: about 47 kg.
  3. No contact involves a pedestal geom at any time (the fixed base, the moving plate), so nothing but the joint limit stops the lift.
  4. The base does not lean: its tilt stays under 1 degree at every setpoint.
Prints the shoulder height above the floor at each setpoint, the workbench top and the straight-arm reach (information, no check).
"""

import math
import sys
from pathlib import Path

import mujoco
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src import robot_specs  # noqa: E402
from src.pedestal import pedestal_load  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402

SCENE = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]
PS = robot_specs.PEDESTAL_SPECS
LO, HI = PS["range"]
HOLD_S, MOVE_S, TOL_MM = 3.0, 15.0, 2.0
SETPOINTS = [("fully raised", HI), ("mid", HI / 2), ("fully collapsed", LO), ("fully raised again", HI)]
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    sim = RobotSimulator(model_path=str(SCENE), cameras=None, pedestal_lift=PS)
    m, d = sim.model, sim.data
    ped = m.actuator(PS["actuator_name"]).id
    jid = m.joint(PS["joints"][0])
    q = lambda: float(d.qpos[jid.qposadr[0]])
    wheels = {m.actuator("left_motor").id, m.actuator("right_motor").id}
    arm_a = [a for s in ("left", "right") for a in arm_ids(m, s)["act"]]
    base_dof = int(m.jnt_dofadr[[j for j in range(m.njnt) if m.jnt_type[j] == mujoco.mjtJoint.mjJNT_FREE][0]])
    d.qpos[0:3] = SPAWN
    hold = np.zeros(m.nu)
    hold[ped] = PS["target_height"]
    mujoco.mj_forward(m, d)

    from src.gravity_ff import for_tests
    ff = for_tests(m)                                    # M185: the arms' gravity as a feedforward unless the setting is "physics"

    def step():
        d.ctrl[:] = hold
        ff.apply(d.ctrl, d)
        d.ctrl[list(wheels)] = 0.0
        d.qvel[base_dof:base_dof + 2] = 0.0
        d.qvel[base_dof + 3:base_dof + 6] = 0.0
        mujoco.mj_step(m, d)

    for a in arm_a + [m.actuator(f"{s}_gripper_ctrl").id for s in ("left", "right")]:      # the arms hold the start pose (zero) and the grippers stay open at zero
        hold[a] = 0.0
    for _ in range(int(1.5 * robot_specs.PHYSICS_HZ)):
        step()

    print("1. load")
    ld = pedestal_load(m, PS)
    print(f"  {ld['mass_above_joint_kg']:.2f} kg sit above the joint, {ld['carried_mass_kg']:.2f} kg of it load the lift (the arms' gravity compensation carries the rest): {ld['hold_force_n']:.0f} N; predicted static sag at kp {PS['kp']:.3g} N/m: {ld['static_sag_mm']:.2f} mm "
          f"(forcerange {PS['force_limit']:.0f} N = {PS['force_limit'] / ld['hold_force_n']:.1f}x the hold force)")
    check("the force range is at least 3x the hold force", PS["force_limit"] >= 3 * ld["hold_force_n"])

    torso, base = m.body("openarm_body_link0").id, m.body("pedestal_base").id
    ped_geoms = {g for g in range(m.ngeom) if m.body(m.geom_bodyid[g]).name in ("pedestal_base", "pedestal_top")}
    rootb = m.body("base_link").id

    def tilt_deg():
        return math.degrees(math.acos(min(1.0, float(d.xmat[rootb].reshape(3, 3)[2, 2]))))

    shoulder = m.joint("openarm_left_joint1").id
    bench_top = float(d.geom_xpos[m.geom("bench_top").id][2] + m.geom_size[m.geom("bench_top").id][2])
    d3 = mujoco.MjData(m)
    d3.qpos[:] = d.qpos
    for a in range(1, 8):
        d3.qpos[m.jnt_qposadr[m.joint(f"openarm_left_joint{a}").id]] = 0.0
    mujoco.mj_kinematics(m, d3)
    reach = float(np.linalg.norm(d3.xpos[m.body("openarm_left_hand_tcp").id] - d3.xanchor[shoulder]))

    print("\n2. setpoints")
    print(f"  {'setpoint':20s} {'reached':>9s} | {'joint err (mm)':>15s} {'torso err (mm)':>15s} {'force (N)':>10s} | {'shoulder z':>10s} {'tilt':>6s}")
    shoulders, any_ped_contact, max_tilt = {}, 0, 0.0
    for name, target in SETPOINTS:
        hold[ped] = target
        t_reach = None
        for k in range(int(round(MOVE_S * robot_specs.PHYSICS_HZ))):
            step()
            any_ped_contact += sum(1 for i in range(d.ncon) if d.contact[i].geom1 in ped_geoms or d.contact[i].geom2 in ped_geoms)
            if abs(q() - target) * 1000 < TOL_MM and t_reach is None:
                t_reach = k / robot_specs.PHYSICS_HZ
        err, terr, force = [], [], []
        for _ in range(int(round(HOLD_S * robot_specs.PHYSICS_HZ))):
            step()
            any_ped_contact += sum(1 for i in range(d.ncon) if d.contact[i].geom1 in ped_geoms or d.contact[i].geom2 in ped_geoms)
            err.append(1000 * (q() - target))
            terr.append(1000 * ((d.xpos[torso][2] - d.xpos[base][2]) - (PS["collapsed_height"] + q())))
            force.append(float(d.actuator_force[ped]))
            max_tilt = max(max_tilt, tilt_deg())
        shoulders[name] = float(d.xanchor[shoulder][2])
        print(f"  {name:20s} {('%.1f s' % t_reach) if t_reach is not None else 'NOT in 15s':>9s} | {err[-1]:+8.2f} ({np.abs(err).max():4.2f}) {terr[-1]:+8.2f} ({np.abs(terr).max():4.2f}) "
              f"{force[-1]:10.0f} | {shoulders[name]:8.3f} m {tilt_deg():5.2f}")
        check(f"{name}: within {TOL_MM:g} mm in {MOVE_S:g} s", t_reach is not None)
        check(f"{name}: held within 1.5 mm for {HOLD_S:g} s", np.abs(err).max() < 1.5, f"max {np.abs(err).max():.2f} mm")
        check(f"{name}: the torso is 0.3048 + command above the pedestal base (within 2 mm)", np.abs(terr).max() < 2.0, f"max {np.abs(terr).max():.2f} mm")
        if target > LO:
            check(f"{name}: the actuator force is the weight it carries (within 15 %)", abs(force[-1] - ld["hold_force_n"]) < 0.15 * ld["hold_force_n"], f"{force[-1]:.0f} N against {ld['hold_force_n']:.0f} N")
        else:          # on the joint limit (command = limit) the limit may take part of the weight, so the actuator carries at most it
            check(f"{name}: the actuator force is at most the weight it carries", 0 <= force[-1] <= 1.15 * ld["hold_force_n"], f"{force[-1]:.0f} N against {ld['hold_force_n']:.0f} N")
    print("\n3. contacts and lean")
    check("no contact ever involves a pedestal geom", any_ped_contact == 0, f"{any_ped_contact} contact samples")
    check("the base's tilt stays under 1 degree at every setpoint", max_tilt < 1.0, f"max {max_tilt:.2f} degrees")

    print(f"\nShoulder height above the floor (left arm joint 1): " + ", ".join(f"{k} {v:.3f} m" for k, v in shoulders.items()))
    print(f"Workbench top z = {bench_top:.3f} m; straight-arm reach from the shoulder {reach:.3f} m: at the collapsed height the bench top is "
          f"{'within' if abs(shoulders['fully collapsed'] - bench_top) <= reach else 'out of'} reach vertically.")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
